<?php
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
require_once __DIR__ . '/../helpers/entrega_imagem_etapa_helper.php';
require_once __DIR__ . '/../helpers/obra_nas_path_helper.php';
$checks = 0;
$failures = [];
$check = static function (bool $ok, string $name) use (&$checks, &$failures) { $checks++; if (!$ok) $failures[] = $name; };
$task = static fn ($f, $s, $extra = []) => $extra + ['funcao_id' => $f, 'status' => $s];
$resolve = static fn ($tasks, $r = null, $p = null, $image = []) => flow_entrega_resolver_etapa($image, $tasks, $r, $p);
$is = static function ($r, $code, $state, $name) use ($check) {
    $check($r['atual']['codigo'] === $code && $r['atual']['situacao'] === $state, $name);
};
$is($resolve([$task(2, 'Em andamento'), $task(4, 'Não iniciado')]), 'MODELAGEM', 'EM_EXECUCAO', 'Future task must not replace execution');
$is($resolve([$task(1, 'Finalizado'), $task(8, 'Em aprovação')]), 'CADERNO_FILTRO', 'AGUARDANDO_APROVACAO', 'Both Caderno/Filtro members must finish');
$cf = $resolve([$task(1, 'Finalizado', ['colaborador_id' => 1]), $task(8, 'Em aprovação', ['colaborador_id' => 2])]);
$check(array_column($cf['atual']['responsaveis'], 'id') === [2], 'Current responsible excludes completed grouped members');
$is($resolve([$task(2, 'HOLD')]), 'MODELAGEM', 'BLOQUEADA', 'HOLD retains stage');
$is($resolve([$task(6, 'Ajuste')]), 'FINALIZACAO', 'EM_AJUSTE', 'Alteração maps to Finalização');
$is($resolve([$task(3, 'Em aprovação')]), 'COMPOSICAO', 'AGUARDANDO_APROVACAO', 'Approval is not completed');
$is($resolve([$task(1, 'Cancelado'), $task(2, 'Não se aplica'), $task(3, 'Não iniciado')]), 'COMPOSICAO', 'AGUARDANDO_INICIO', 'Skip nonapplicable tasks');
$is($resolve([$task(2, 'Em andamento', ['colaborador_id' => 15]), $task(4, 'Não iniciado')]), 'FINALIZACAO', 'AGUARDANDO_INICIO', 'Skip operational placeholder');
$is($resolve([$task(4, 'Aprovado com ajustes')]), 'RENDER', 'AGUARDANDO_ENVIO', 'Completed Finalização needs handoff');
$is($resolve([$task(5, 'Em andamento')]), 'INDEFINIDA', 'INDEFINIDA', 'Unreleased Post task cannot win');
$parallel = $resolve([$task(2, 'Em andamento'), $task(4, 'Em andamento')]);
$check(count($parallel['simultaneas']) === 2 && $parallel['atual']['codigo'] === 'MODELAGEM', 'Preserve parallel execution and first blocker');
$is($resolve([$task(2, 'Em aprovação', ['unidade_id' => 1]), $task(3, 'Em aprovação', ['unidade_id' => 1])]), 'COMPOSICAO', 'AGUARDANDO_APROVACAO', 'Respect Modelagem/Composição unit representative');
$render = ['id' => 1, 'status' => 'Não iniciado', 'origem' => 'RENDER', 'referencia_em' => '2026-10-20 10:00:00'];
$is($resolve([], $render), 'RENDER', 'NA_FILA', 'Requested render enters queue');
$is($resolve([], array_replace($render, ['tentativa_status' => 'EM_ANDAMENTO'])), 'RENDER', 'EM_EXECUCAO', 'Current Deadline attempt');
$is($resolve([], array_replace($render, ['tentativa_status' => 'EM_ANDAMENTO', 'processamento_status' => 'Queued'])), 'RENDER', 'NA_FILA', 'Queued Deadline task is not rendering');
$is($resolve([], array_replace($render, ['tentativa_status' => 'EM_APROVACAO'])), 'RENDER', 'AGUARDANDO_APROVACAO', 'Completed job awaits approval');
$is($resolve([], array_replace($render, ['tentativa_status' => 'CONCLUIDA_MANUALMENTE'])), 'RENDER', 'AGUARDANDO_APROVACAO', 'Manual completion still awaits approval');
$is($resolve([], array_replace($render, ['status' => 'Reprovado'])), 'RENDER', 'REPROVADO', 'Rejected stays in Render without reopening');
$is($resolve([], array_replace($render, ['status' => 'Refazendo'])), 'RENDER', 'REFAZENDO', 'Resubmission stays in Render');
$is($resolve([], array_replace($render, ['status' => 'Erro'])), 'RENDER', 'ERRO', 'Render error stays visible');
$is($resolve([$task(4, 'Em andamento', ['alterado_em' => '2026-10-21 10:00:00'])], $render), 'FINALIZACAO', 'EM_EXECUCAO', 'Explicit scene reopening supersedes old render');
$is($resolve([$task(4, 'Em andamento', ['alterado_em' => '2026-10-19 10:00:00'])], $render), 'RENDER', 'NA_FILA', 'Stale task cannot supersede newer render');
$approved = array_replace($render, ['status' => 'Aprovado']);
$is($resolve([], $approved), 'POS_PRODUCAO', 'AGUARDANDO_ENVIO', 'Approved without Post handoff');
$pos = ['id' => 2, 'status_pos' => 1, 'origem' => 'POS_PRODUCAO'];
$is($resolve([], $approved, $pos), 'POS_PRODUCAO', 'AGUARDANDO_INICIO', 'Post release is not execution');
$is($resolve([$task(5, 'Em andamento')], $approved, $pos), 'POS_PRODUCAO', 'EM_EXECUCAO', 'Post execution requires task and handoff');
$is($resolve([$task(5, 'Finalizado')], $approved, $pos), 'POS_PRODUCAO', 'AGUARDANDO_INICIO', 'Old completed Post task does not finish new handoff');
$is($resolve([], $approved, array_replace($pos, ['status_pos' => 0])), 'POS_PRODUCAO', 'CONCLUIDA', 'Post completion comes from current matching row');
$is($resolve([], $approved, null, ['tipo_imagem' => 'Planta Humanizada']), 'RENDER', 'CONCLUIDA', 'Planta skips Post');
$is($resolve([], $approved, null, ['ciclo_nome' => 'P00']), 'RENDER', 'CONCLUIDA', 'P00 skips Post');
$atalho = static fn ($r, $ts, $c = 'R00') => flow_entrega_tarefa_atalho($r, $ts, $c)['funcao_imagem_id'] ?? null;
$tFinal = $task(4, 'Finalizado', ['tarefa_id' => 400]);
$tAlter = $task(6, 'Finalizado', ['tarefa_id' => 600]);
$check($atalho($resolve([$tFinal], $render), [$tFinal]) === 400, 'Render links to function instead of render ID');
$check($atalho($resolve([$tFinal, $tAlter], $render), [$tFinal, $tAlter], 'R01') === 600, 'Revision render links to Alteracao');
$tPos = $task(5, 'Finalizado', ['tarefa_id' => 500]);
$check($atalho($resolve([$tPos], $approved, $pos), [$tPos]) === 500, 'Post links to function instead of Post row ID');
$tModel = $task(2, 'Finalizado', ['tarefa_id' => 200]);
$check($atalho($resolve([$tModel], $approved, null, ['ciclo_nome' => 'P00']), [$tModel], 'P00') === 200, 'P00 render links to Modelagem');
$check($atalho($resolve([], $render), []) === null, 'Missing function does not create a misleading link');
$planned = $task(4, 'Não iniciado', ['origem' => 'PLANEJAMENTO', 'id' => 900]);
$check($atalho($resolve([$planned]), [$planned]) === null, 'Planned allocation is not a task card');
$tCaderno = $task(1, 'Finalizado', ['tarefa_id' => 100]);
$tFiltro = $task(8, 'Em aprovação', ['tarefa_id' => 800]);
$check($atalho($resolve([$tCaderno, $tFiltro]), [$tCaderno, $tFiltro]) === 800, 'Grouped stage opens current member');
$found = flow_obra_nas_descobrir('ABC_PROJ', ['2025', '2026', '2027', '.', '..', 'arquivo'], static fn ($y) => $y === '2027');
$check($found['base'] === 'Z:\\2027\\ABC_PROJ', 'Discover years without hardcoded list');
$check(flow_obra_nas_descobrir('ABC_PROJ', ['2025', '2026'], static fn () => true)['estado'] === 'AMBIGUO', 'Do not select first of duplicate roots');
$check(flow_obra_nas_descobrir('ABC_PROJ', ['2025'], static fn () => false)['base'] === null, 'No guessed year for missing folder');
$check(flow_obra_nas_descobrir('../ABC', ['2026'], static fn () => true)['base'] === null, 'Reject unsafe project segments');
$base = 'Z:\\2025\\ABC_PROJ';
$check(flow_entrega_nas_caminho($base, 'R01') === $base . '\\04.Finalizacao\\R01', 'Use storage year independently of current date');
$check(flow_entrega_nas_caminho($base, 'P00', ['versao_label' => 'V3']) === $base . '\\03.Models\\Modelagem_Fachada\\Toons\\V3', 'P00 version path');
$check(flow_entrega_nas_caminho($base, 'P00', ['nas_path' => '../outro']) === null, 'Reject unsafe relative NAS path');
$check(flow_entrega_nas_caminho($base, '../fora') === null, 'Reject unsafe delivery cycle');
echo json_encode(compact('checks', 'failures'), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . PHP_EOL;
exit($failures ? 1 : 0);
